3	namespace App\Support;
4	
5	/**
6	 * Mealie's GUID column type (mealie/db/models/_model_utils/guid.py):
7	 * SQLite stores CHAR(32) lowercase hex without dashes; the API returns dashed UUIDs.
8	 */
9	class Guid
10	{
11	    /** Dashed or plain UUID string -> 32-char hex for SQLite WHERE clauses. Null if not a UUID. */
12	    public static function toDb(?string $value): ?string
13	    {
14	        if ($value === null) {
15	            return null;
16	        }
17	        $hex = strtolower(str_replace(['-', '{', '}'], '', trim($value)));
18	
19	        return preg_match('/^[0-9a-f]{32}$/', $hex) ? $hex : null;
20	    }
21	
22	    /** 32-char hex from SQLite -> dashed lowercase UUID for JSON. */
23	    public static function fromDb(?string $value): ?string
24	    {
25	        if ($value === null || $value === '') {
26	            return null;
27	        }
28	        $hex = self::toDb($value);
29	        if ($hex === null) {
30	            return $value;
31	        }
32	
33	        return substr($hex, 0, 8).'-'.substr($hex, 8, 4).'-'.substr($hex, 12, 4).'-'.substr($hex, 16, 4).'-'.substr($hex, 20, 12);
34	    }
35	
36	    public static function isUuid(?string $value): bool
37	    {
38	        return self::toDb($value) !== null;
39	    }
40	
41	    /** Pydantic UUID4 also checks the version nibble; 00000000-... fails with 422. */
42	    public static function isUuid4(?string $value): bool
43	    {
44	        $hex = self::toDb($value);
45	
46	        return $hex !== null && $hex[12] === '4';
47	    }
48	
49	    /**
50	     * Validate a path/query/body value declared as UUID4 in the Python route and return its DB form.
51	     * Fails the request with FastAPI's 422 shape otherwise.
52	     */
53	    public static function requireUuid4(?string $value, string $loc = 'path'): string
54	    {
55	        if (! self::isUuid4($value)) {
56	            Errors::validation("UUID version 4 expected at {$loc}");
57	        }
58	
59	        return self::toDb($value);
60	    }
61	
62	    /** Same, for routes declared as plain UUID (no version check). */
63	    public static function requireUuid(?string $value, string $loc = 'path'): string
64	    {
65	        if (! self::isUuid($value)) {
66	            Errors::validation("Input should be a valid UUID at {$loc}");
67	        }
68	
69	        return self::toDb($value);
70	    }
71	
72	    public static function new(): string
73	    {
74	        return str_replace('-', '', (string) \Illuminate\Support\Str::uuid());
75	    }
76	}
