CREATE TABLE categories (
	created_at DATETIME, 
	update_at DATETIME, 
	group_id CHAR(32) NOT NULL, 
	id CHAR(32) NOT NULL, 
	name VARCHAR NOT NULL, 
	slug VARCHAR NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(group_id) REFERENCES groups (id), 
	CONSTRAINT category_slug_group_id_key UNIQUE (slug, group_id)
);
